import { randomBytes } from 'node:crypto';
import { storedType } from './file-types';

/** Storage prefixes (directories) that browser-direct uploads may write to. */
export const DIRECT_UPLOAD_PREFIX = 'downloads/';
export const VIDEO_UPLOAD_PREFIX = 'videos/';

const KEY_PATTERN = /^[a-z]+\/[0-9a-f]{32}(\.[a-z0-9]{1,10})?$/;

/** True for keys of the form `<prefix><32 hex>[.ext]` (default prefix `downloads/`), i.e. generated by `newDirectUploadKey`. */
export function isDirectUploadKey(key: string, prefix: string = DIRECT_UPLOAD_PREFIX): boolean {
    return key.startsWith(prefix) && KEY_PATTERN.test(key);
}

/** Server-generated, unguessable `<prefix><random>.<ext>` key with an allowlisted extension; the browser never chooses the key. */
export function newDirectUploadKey(
    fileName: string,
    contentType: string,
    prefix: string = DIRECT_UPLOAD_PREFIX,
): string {
    return `${prefix}${randomBytes(16).toString('hex')}${storedType(fileName, contentType).ext}`;
}
